/**
 * Which byte measurement a view should display.
 */

public enum SizeMetric: Equatable, Hashable {
    
    /**
     * Apparent file length, counting each inode or clone group once.
     * This is the default chart metric: it is stable across filesystems and
     * matches what a user sees in a file inspector.
     */
    case uniqueApparent
    /**
     * Allocated blocks (`st_blocks * 512`), counting each shared identity once.
     * Closer to `du` and to the space a delete would reclaim, except that
     * APFS snapshots and purgeable space are still not included.
     */
    case uniqueAllocated
    /**
     * Apparent length summed once per path, so hard links and followed
     * symlinks are counted again at every name.
     */
    case logicalApparent





}

#if compiler(>=6)
extension SizeMetric: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSizeMetric: FfiConverterRustBuffer {
    typealias SwiftType = SizeMetric

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SizeMetric {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .uniqueApparent
        
        case 2: return .uniqueAllocated
        
        case 3: return .logicalApparent
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SizeMetric, into buf: inout [UInt8]) {
        switch value {
        
        
        case .uniqueApparent:
            writeInt(&buf, Int32(1))
        
        
        case .uniqueAllocated:
            writeInt(&buf, Int32(2))
        
        
        case .logicalApparent:
            writeInt(&buf, Int32(3))
        
        }
    }
}


